 throw new Error('CONFIG_INVALID: Invalid API timeout or model.');
if (!Array.isArray(config.allowedCurrencies) || !config.allowedCurrencies.length || config.allowedCurrencies.some(c=>typeof c!=='string'||!(/^[A-Z]{3}$/.test(c))))
 throw new Error('CONFIG_INVALID: Invalid currency list.');
