    },
    currency: {
      type: ['string', 'null'],
      description: 'ISO currency code supported by the document; otherwise null'
    },
    net_amount: {
      type: ['number', 'null'],
      description: 'Explicitly stated net amount as a number; otherwise null'
    },
    tax_amount: {
      type: ['number', 'null'],
