const fields={invoice_number:'string',invoice_date:'string',supplier:'string',total_amount:'number',currency:'string',net_amount:'number',tax_amount:'number',due_date:'string',vat_id:'string',description:'string',confidence:'number'};
function validDate(v) {if(typeof v!=='string' || !/^\d{4}-\d{2}-\d{2}$/.test(v))return false; const d=new Date(v+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===v;}
function amount(v){
 if(typeof v==='number')return Number.isFinite(v)?v:NaN;
 if(typeof v!=='string')return NaN;
 const s=v.trim();
 if(/^-?\d{1,3}(\.\d{3})*,\d{1,2}$/.test(s) || /^-?\d+,\d{1,2}$/.test(s))return Number(s.replace(/\./g,'').replace(',','.'));
 if(/^-?\d+(\.\d{1,2})?$/.test(s))return Number(s);
 return NaN;
}
function canonical(s){return String(s).normalize('NFKC').trim().toLocaleLowerCase('de-DE').replace(/\s+/g,' ');}
return $input.all().map((item,i)=>{
 const j=item.json; const inv=j.invoice ? {...j.invoice}:{}; const reasons=[...(j.reasons || [])];
 for(const k of Object.keys(inv))if(!Object.prototype.hasOwnProperty.call(fields,k))reasons.push('SCHEMA_EXTRA_FIELD');
 for(const [k,t] of Object.entries(fields)){
