 if(['net_amount','tax_amount','total_amount'].every(k=>typeof inv[k]==='number'&&Number.isFinite(inv[k])) &&
 Math.abs(inv.net_amount+inv.tax_amount-inv.total_amount)>j.config.roundingTolerance+1e-9)reasons.push('AMOUNT_MISMATCH');
 if(inv.confidence!==null && (typeof inv.confidence!=='number'||inv.confidence<0||inv.confidence>1))reasons.push('INVALID_confidence');
 if(j.config.minSelfReportedConfidence!==null && (inv.confidence===null || inv.confidence<j.config.minSelfReportedConfidence))reasons.push('LOW_SELF_REPORTED_CONFIDENCE');
 const valid=reasons.length===0;
 const duplicateKey=valid?JSON.stringify([canonical(inv.supplier),canonical(inv.invoice_number),inv.invoice_date,inv.currency]):'';
 return {json:{...j,invoice:inv,reasons:[...new Set(reasons)],valid,duplicateKey,step:'Validate Invoice'},pairedItem:{item:i}};
});

