 row['Review Reason']=safe((j.reasons || []).join(';'));row['File Name']=safe(j.fileName);row['Subject']=safe(j.subject);row['Received At']=safe(j.receivedAt);row['Execution ID']=String($execution.id);row['Review Key']=safe(j.reference);
