  const chars=raw.reduce((n,s)=>n+s.length,0);
  if(chars<ctx.config.ocrMinTextChars)reason='OCR_TEXT_EMPTY_OR_TOO_SHORT';
  else if(chars>ctx.config.ocrMaxTextChars)reason='OCR_TEXT_TOO_LARGE';
  else text=raw.map((s,index)=>'[Page '+(index+1)+']\n'+s).join('\n\n');
 }
